(876, 'xts-theme_settings_default-css-data', ':root {\n	--wd-text-font: \"Jost\", Arial, Helvetica, sans-serif;\n	--wd-text-font-weight: 400;\n	--wd-text-color: #767676;\n	--wd-text-font-size: 14px;\n	--wd-title-font: \"hkgroteskpro\", Arial, Helvetica, sans-serif;\n	--wd-title-font-weight: 600;\n	--wd-title-color: #242424;\n	--wd-entities-title-font: \"hkgroteskpro\", Arial, Helvetica, sans-serif;\n	--wd-entities-title-font-weight: 600;\n	--wd-entities-title-color: #333333;\n	--wd-entities-title-color-hover: rgb(51 51 51 / 65%);\n	--wd-alternative-font: \"hkgroteskpro\", Arial, Helvetica, sans-serif;\n	--wd-widget-title-font: \"hkgroteskpro\", Arial, Helvetica, sans-serif;\n	--wd-widget-title-font-weight: 600;\n	--wd-widget-title-transform: uppercase;\n	--wd-widget-title-color: #333;\n	--wd-widget-title-font-size: 16px;\n	--wd-header-el-font: \"hkgroteskpro\", Arial, Helvetica, sans-serif;\n	--wd-header-el-font-weight: 600;\n	--wd-header-el-transform: none;\n	--wd-header-el-font-size: 14px;\n	--wd-otl-style: dotted;\n	--wd-otl-width: 2px;\n	--wd-primary-color: rgb(46,107,198);\n	--wd-alternative-color: #fbbc34;\n	--btn-default-bgcolor: #f7f7f7;\n	--btn-default-bgcolor-hover: #efefef;\n	--btn-accented-bgcolor: rgb(46,107,198);\n	--btn-accented-bgcolor-hover: rgb(42,97,180);\n	--wd-form-brd-width: 1px;\n	--notices-success-bg: #459647;\n	--notices-success-color: #fff;\n	--notices-warning-bg: #E0B252;\n	--notices-warning-color: #fff;\n	--wd-link-color: #333333;\n	--wd-link-color-hover: #242424;\n}\n.wd-age-verify-wrap {\n	--wd-popup-width: 500px;\n}\n.wd-popup.wd-promo-popup {\n	background-color: #111111;\n	background-image: url(http://localhost/asset-blog/wp-content/uploads/2022/09/accessories-popup.jpg);\n	background-repeat: no-repeat;\n	background-size: cover;\n	background-position: center center;\n}\n.wd-promo-popup-wrap {\n	--wd-popup-width: 800px;\n}\n:is(.woodmart-woocommerce-layered-nav, .wd-product-category-filter) .wd-scroll-content {\n	max-height: 223px;\n}\n.wd-page-title .wd-page-title-bg img {\n	object-fit: cover;\n	object-position: center center;\n}\n.wd-footer {\n	background-color: rgb(16,16,16);\n	background-image: none;\n}\nhtml .product.wd-cat .wd-entities-title, html .product.wd-cat.cat-design-replace-title .wd-entities-title, html .wd-masonry-first .wd-cat:first-child .wd-entities-title {\n	font-size: 18px;\n	text-transform: none;\n}\nhtml .wd-nav-mobile > li > a, html .wd-nav-mobile .wd-sub-menu li a {\n	text-transform: none;\n}\nhtml .btn.wd-buy-now-btn {\n	background: rgb(36,36,36);\n}\nhtml .btn.wd-buy-now-btn:hover {\n	background: rgb(51,51,51);\n}\n.mfp-wrap.wd-popup-quick-view-wrap {\n	--wd-popup-width: 920px;\n}\n:root{\n--wd-container-w: 1320px;\n--wd-form-brd-radius: 5px;\n--btn-default-color: #333;\n--btn-default-color-hover: #333;\n--btn-accented-color: #fff;\n--btn-accented-color-hover: #fff;\n--btn-default-brd-radius: 5px;\n--btn-default-box-shadow: none;\n--btn-default-box-shadow-hover: none;\n--btn-accented-brd-radius: 5px;\n--btn-accented-box-shadow: none;\n--btn-accented-box-shadow-hover: none;\n--wd-brd-radius: 8px;\n}\n\n@media (min-width: 1320px) {\nsection.elementor-section.wd-section-stretch > .elementor-container {\nmargin-left: auto;\nmargin-right: auto;\n}\n}\n\n\n.wd-page-title {\nbackground-color: #0a0a0a;\n}\n\n@font-face {\n	font-family: \"hkgroteskpro\";\n	src: url(\"//localhost/asset-blog/wp-content/uploads/2022/09/hkgroteskpro-semibold.woff\") format(\"woff2\"), \nurl(\"//localhost/asset-blog/wp-content/uploads/2022/09/hkgroteskpro-semibold.woff\") format(\"woff\");\n	font-weight: 600;\n	font-display:swap;\n	font-style: normal;\n}\n\n', 'on'),
