(576, 45, '_form', '<div class=\"wd-grid-g\">\n<div class=\"wd-grid-f-stretch\">\n<div class=\"wd-col\">[text* First name placeholder =\"First name\"]</div>\n<div class=\"wd-col\">[text* Last name placeholder =\"Email\" ]</div>\n</div>\n<div class=\"wd-col\">[text* Email placeholder =\"Email\" ]</div>\n<div class=\"wd-col\">[textarea your-message placeholder =\"Your Message\"]</div>\n<div class=\"wd-col\">[submit class:btn class:btn-color-primary\"Send Message\"]</div>\n</div>'),
