(1891, 27, '_elementor_data', '[{\"id\":\"c552aa2\",\"elType\":\"container\",\"settings\":{\"wd_section_stretch\":\"stretch\",\"background_background\":\"classic\",\"background_color\":\"#F8F8F8\",\"margin\":{\"unit\":\"px\",\"top\":\"-40\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"-40\",\"right\":\"0\",\"bottom\":\"60\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"80\",\"right\":\"15\",\"bottom\":\"80\",\"left\":\"15\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"15\",\"bottom\":\"60\",\"left\":\"15\",\"isLinked\":false},\"flex_direction\":\"column\",\"flex_gap\":{\"size\":null,\"column\":\"\",\"row\":\"\",\"unit\":\"px\",\"isLinked\":true},\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":50,\"sizes\":[]},\"scroll_y\":-80},\"elements\":[{\"id\":\"234c6f6\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/asset-blog\\/wp-content\\/uploads\\/2022\\/09\\/privacy-policy-xtemos-logo.svg\",\"id\":\"74\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"custom\",\"image_custom_dimension\":{\"width\":\"80\",\"height\":\"80\"},\"alignment\":\"center\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_image_or_svg\"},{\"id\":\"1dfc80d\",\"elType\":\"widget\",\"settings\":{\"subtitle\":\"\",\"title\":\"Who We Are\",\"after_title\":\"\",\"size\":\"large\",\"title_typography_typography\":\"custom\",\"title_typography_font_size\":{\"unit\":\"px\",\"size\":36,\"sizes\":[]},\"title_typography_font_size_tablet\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]},\"title_typography_font_size_mobile\":{\"unit\":\"px\",\"size\":26,\"sizes\":[]},\"scroll_y\":-80,\"title_typography_font_family\":\"hkgroteskpro\"},\"elements\":[],\"widgetType\":\"wd_title\"},{\"id\":\"7fe7828\",\"elType\":\"widget\",\"settings\":{\"text\":\"<p>Our website address is: <span style=\\\"color: #2e6bc6;\\\"><strong><a style=\\\"c