(83, 1, '2022-09-07 14:21:11', '2022-09-07 14:21:11', '<link rel=\"stylesheet\" id=\"wd-section-title-css\" href=\"https://dummy.xtemos.com/woodmart2/accessories-elementor/wp-content/themes/woodmart/css/parts/el-section-title.min.css?ver=8.4.0\" type=\"text/css\" media=\"all\" /> 					\n				<h4>Charge Your Phone Safely!</h4> \n		<p>A wonderful serenity has taken possession of my entire soul, like these sweet mornings of spring which I enjoy with my whole heart.</p>		\n								<link rel=\"stylesheet\" id=\"wd-button-css\" href=\"https://dummy.xtemos.com/woodmart2/accessories-elementor/wp-content/themes/woodmart/css/parts/el-button.min.css?ver=8.4.0\" type=\"text/css\" media=\"all\" /> 					\n			<a  href=\"#\">\n					To shop				\n							</a>\n			<a  href=\"#\">\n					Read more				\n							</a>', 'Accessories slide 1', '', 'publish', 'closed', 'closed', '', 'accessories-slide-1', '', '', '2022-09-07 14:21:11', '2022-09-07 14:21:11', '', 0, 'http://dummy.xtemos.com/woodmart2/accessories-elementor/?post_type=woodmart_slide&amp;p=83', 0, 'woodmart_slide', '', 0),
